mapper.select:
SELECT id, user_id AS userId, title, start_time AS startTime, end_time AS endTime,
       note, created_at AS createdAt
FROM personal_schedule
WHERE user_id = #{userId}
  AND start_time < #{to}
  AND end_time > #{from}
ORDER BY start_time

mapper.update:
UPDATE personal_schedule
SET title = #{title}, start_time = #{startTime}, end_time = #{endTime}, note = #{note}
WHERE id = #{id} AND user_id = #{userId}
